alter table public.approvals add constraint approvals_status_check CHECK (status = ANY (ARRAY['pending'::text, 'approved'::text, 'rejected'::text, 'expired'::text]));
alter table public.assets add constraint assets_asset_type_check CHECK (asset_type = ANY (ARRAY['image'::text, 'video'::text, 'audio'::text, 'voice'::text, 'music'::text, 'sfx'::text, 'subtitle'::text, 'thumbnail'::text, 'other'::text]));
alter table public.assets add constraint assets_license_status_check CHECK (license_status = ANY (ARRAY['owned'::text, 'licensed'::text, 'generated'::text, 'public_domain'::text, 'unknown'::text, 'restricted'::text]));
alter table public.automations add constraint automations_config_check CHECK (jsonb_typeof(config) = 'object'::text);
alter table public.automations add constraint automations_kind_check CHECK (kind = ANY (ARRAY['trend_watch'::text, 'opportunity_refresh'::text, 'shorts_factory'::text]));
alter table public.automations add constraint automations_name_check CHECK (char_length(name) >= 1 AND char_length(name) <= 120);
alter table public.automations add constraint automations_schedule_check CHECK (schedule = ANY (ARRAY['manual'::text, 'daily'::text]));
alter table public.automation_runs add constraint automation_runs_status_check CHECK (status = ANY (ARRAY['running'::text, 'succeeded'::text, 'failed'::text]));
alter table public.automation_runs add constraint automation_runs_trigger_check CHECK (trigger = ANY (ARRAY['manual'::text, 'schedule'::text]));
alter table public.campaigns add constraint campaigns_brief_check CHECK (pg_column_size(brief) < 200000);
alter table public.campaigns add constraint campaigns_name_check CHECK (char_length(name) <= 200);
alter table public.campaigns add constraint campaigns_notes_check CHECK (char_length(notes) <= 4000);
alter table public.campaigns add constraint campaigns_status_check CHECK (status = ANY (ARRAY['borrador'::text, 'lista'::text, 'archivada'::text]));
alter table public.channel_connections add constraint channel_connections_status_check CHECK (status = ANY (ARRAY['connected'::text, 'expired'::text, 'revoked'::text, 'error'::text]));
alter table public.generation_spend add constraint generation_spend_estimate_usd_check CHECK (estimate_usd >= (0)::numeric);
alter table public.opportunities add constraint opportunities_confidence_check CHECK (confidence IS NULL OR (confidence >= (0)::numeric AND confidence <= (1)::numeric));
alter table public.opportunities add constraint opportunities_status_check CHECK (status = ANY (ARRAY['discovered'::text, 'research_needed'::text, 'candidate'::text, 'experiment_approved'::text, 'discarded'::text]));
alter table public.projects add constraint projects_status_check CHECK (status = ANY (ARRAY['draft'::text, 'research'::text, 'production'::text, 'review'::text, 'ready'::text, 'published'::text, 'archived'::text]));
alter table public.publication_jobs add constraint publication_jobs_status_check CHECK (status = ANY (ARRAY['draft'::text, 'awaiting_approval'::text, 'approved'::text, 'queued'::text, 'publishing'::text, 'published'::text, 'failed'::text, 'cancelled'::text]));
alter table public.render_jobs add constraint render_jobs_output_format_check CHECK (output_format = ANY (ARRAY['16:9'::text, '9:16'::text, '1:1'::text]));
alter table public.render_jobs add constraint render_jobs_status_check CHECK (status = ANY (ARRAY['draft'::text, 'queued'::text, 'rendering'::text, 'completed'::text, 'failed'::text, 'cancelled'::text]));
alter table public.research_cache add constraint research_cache_searches_check CHECK (searches >= 0);
alter table public.research_cache add constraint research_cache_units_check CHECK (units >= 0);
alter table public.scenes add constraint scenes_duration_ms_check CHECK (duration_ms > 0);
alter table public.scripts add constraint scripts_sections_check CHECK (jsonb_typeof(sections) = 'array'::text);
alter table public.scripts add constraint scripts_status_check CHECK (status = ANY (ARRAY['draft'::text, 'review'::text, 'approved'::text, 'archived'::text]));
alter table public.scripts add constraint scripts_title_check CHECK (char_length(title) >= 1 AND char_length(title) <= 200);
alter table public.scripts add constraint scripts_version_check CHECK (version > 0);
alter table public.shorts_factory_items add constraint shorts_factory_items_status_check CHECK (status = ANY (ARRAY['prepared'::text, 'approved'::text, 'published'::text, 'discarded'::text, 'failed'::text]));
alter table public.shorts_factory_items add constraint shorts_factory_items_topic_check CHECK (char_length(topic) >= 1 AND char_length(topic) <= 200);
