create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path to '' as $$
begin
  insert into public.profiles (id, display_name) values (new.id, coalesce(new.raw_user_meta_data ->> 'name', new.email));
  return new;
end;
$$;
create or replace function public.research_lock(p_key text, p_ttl_seconds integer) returns boolean language plpgsql as $$
declare uid uuid := (select auth.uid()); got uuid;
begin
  if uid is null then return false; end if;
  insert into public.research_cache (owner_id, cache_key, kind, payload, units, fetched_at, expires_at)
  values (uid, p_key, 'lock', '{}'::jsonb, 0, now(), now() + make_interval(secs => greatest(p_ttl_seconds, 1)))
  on conflict (owner_id, cache_key) do update set kind = 'lock', fetched_at = now(), expires_at = excluded.expires_at
    where public.research_cache.expires_at <= now()
  returning id into got;
  return got is not null;
end $$;
create or replace function public.research_quota_day_start() returns timestamptz language sql stable as $$
  select date_trunc('day', now() at time zone 'America/Los_Angeles') at time zone 'America/Los_Angeles'
$$;
create or replace function public.research_reserve(p_key text, p_units integer, p_cap integer, p_ttl_seconds integer, p_searches integer default 0, p_search_cap integer default 1000000) returns jsonb language plpgsql as $$
declare uid uuid := (select auth.uid()); used integer; used_s integer;
begin
  if uid is null then return jsonb_build_object('ok', false, 'reason', 'no_session', 'used', 0, 'used_searches', 0); end if;
  if p_units < 0 or p_cap < 0 or p_searches < 0 or p_search_cap < 0 then raise exception 'invalid budget'; end if;
  perform pg_advisory_xact_lock(hashtextextended('research_reserve:' || uid::text, 0));
  select coalesce(sum(units), 0), coalesce(sum(searches), 0) into used, used_s from public.research_cache where owner_id = uid and fetched_at >= public.research_quota_day_start();
  if used + p_units > p_cap then return jsonb_build_object('ok', false, 'reason', 'budget', 'used', used, 'used_searches', used_s); end if;
  if used_s + p_searches > p_search_cap then return jsonb_build_object('ok', false, 'reason', 'search_budget', 'used', used, 'used_searches', used_s); end if;
  insert into public.research_cache (owner_id, cache_key, kind, payload, units, searches, fetched_at, expires_at)
  values (uid, p_key, 'reserve', '{}'::jsonb, p_units, p_searches, now(), now() + make_interval(secs => greatest(p_ttl_seconds, 1)))
  on conflict (owner_id, cache_key) do update set kind = 'reserve', units = excluded.units, searches = excluded.searches, fetched_at = now(), expires_at = excluded.expires_at;
  return jsonb_build_object('ok', true, 'used', used + p_units, 'used_searches', used_s + p_searches);
end $$;
create or replace function public.vi_check_ownership() returns trigger language plpgsql security definer set search_path to 'public' as $$
begin
  if tg_table_name = 'vi_personas' then
    if not exists (select 1 from public.projects where id = new.project_id and owner_id = new.owner_id) then
      raise exception 'Project does not belong to the persona owner.';
    end if;
    return new;
  end if;
  if not exists (select 1 from public.vi_personas where id = new.persona_id and owner_id = new.owner_id) then
    raise exception 'Persona does not belong to this owner.';
  end if;
  if tg_table_name = 'vi_references' then
    if not exists (select 1 from public.assets where id = new.asset_id and owner_id = new.owner_id) then
      raise exception 'Asset does not belong to this owner.';
    end if;
  elsif tg_table_name = 'vi_generation_jobs' then
    if new.output_asset_id is not null then
      if not exists (select 1 from public.assets where id = new.output_asset_id and owner_id = new.owner_id) then
        raise exception 'Output asset does not belong to this owner.';
      end if;
    end if;
  end if;
  return new;
end $$;
create or replace function public.vi_identity_versions_lock() returns trigger language plpgsql set search_path to 'public' as $$
begin
  if old.status in ('approved', 'superseded') then
    if new.traits is distinct from old.traits or new.reference_asset_ids is distinct from old.reference_asset_ids
       or new.version is distinct from old.version or new.persona_id is distinct from old.persona_id
       or (old.status = 'superseded' and new.status <> 'superseded')
       or (old.status = 'approved' and new.status not in ('approved', 'superseded')) then
      raise exception 'Approved identity versions are immutable; create a new version instead.';
    end if;
  end if;
  return new;
end $$;
-- Function privileges as in Production (default PUBLIC execute is revoked, then granted explicitly).
revoke all on function public.handle_new_user() from public, anon, authenticated;
revoke all on function public.vi_check_ownership() from public, anon, authenticated;
revoke all on function public.vi_identity_versions_lock() from public, anon, authenticated;
revoke all on function public.research_lock(text, integer) from public, anon;
revoke all on function public.research_reserve(text, integer, integer, integer, integer, integer) from public, anon;
grant execute on function public.handle_new_user(), public.vi_check_ownership(), public.vi_identity_versions_lock() to service_role;
grant execute on function public.research_lock(text, integer), public.research_reserve(text, integer, integer, integer, integer, integer) to authenticated, service_role;
grant execute on function public.research_quota_day_start() to public, anon, authenticated, service_role;

create trigger vi_generation_jobs_ownership before insert or update on public.vi_generation_jobs for each row execute function public.vi_check_ownership();
create trigger vi_identity_versions_lock before update on public.vi_identity_versions for each row execute function public.vi_identity_versions_lock();
create trigger vi_identity_versions_ownership before insert or update on public.vi_identity_versions for each row execute function public.vi_check_ownership();
create trigger vi_personas_ownership before insert or update on public.vi_personas for each row execute function public.vi_check_ownership();
create trigger vi_quality_reports_ownership before insert or update on public.vi_quality_reports for each row execute function public.vi_check_ownership();
create trigger vi_references_ownership before insert or update on public.vi_references for each row execute function public.vi_check_ownership();
create trigger vi_scenes_ownership before insert or update on public.vi_scenes for each row execute function public.vi_check_ownership();
create trigger vi_voice_profiles_ownership before insert or update on public.vi_voice_profiles for each row execute function public.vi_check_ownership();
create trigger vi_wardrobe_ownership before insert or update on public.vi_wardrobe for each row execute function public.vi_check_ownership();
-- NOT reproduced here: the auth.users trigger that calls handle_new_user() lives in the auth schema (managed by Supabase).

-- RLS policies. Owner-only "for all" policies:
do $$ declare r record; begin
  for r in select * from (values
    ('profiles','profiles_own','public','id'),('projects','projects_own','public','owner_id'),('assets','assets_own','public','owner_id'),
    ('opportunities','opportunities_own','public','owner_id'),('metric_snapshots','metrics_own','public','owner_id'),
    ('storyboards','storyboards_own','public','owner_id'),('scenes','scenes_own','public','owner_id'),('render_jobs','render_jobs_own','public','owner_id'),
    ('connector_configs','connector_configs_own','public','owner_id'),('scripts','scripts_owner_all','public','owner_id'),
    ('trend_snapshots','trend_snapshots_owner_all','public','owner_id'),('automations','automations_owner_all','public','owner_id'),
    ('automation_runs','automation_runs_owner_all','public','owner_id'),('shorts_factory_items','shorts_factory_items_owner_all','public','owner_id'),
    ('research_cache','research_cache_owner_all','authenticated','owner_id')) as v(t,p,ro,c)
  loop execute format('create policy %I on public.%I for all to %s using (%I = (select auth.uid())) with check (%I = (select auth.uid()))', r.p, r.t, r.ro, r.c, r.c); end loop;
  for r in select unnest(array['vi_personas','vi_identity_versions','vi_references','vi_voice_profiles','vi_scenes','vi_wardrobe','vi_generation_jobs','vi_quality_reports']) t
  loop execute format('create policy %I on public.%I for all to public using (owner_id = auth.uid()) with check (owner_id = auth.uid())', r.t||'_owner_all', r.t); end loop;
end $$;
create policy audit_log_read_own on public.audit_log for select to public using (owner_id = (select auth.uid()));
create policy approvals_owner_read on public.approvals for select to authenticated using (owner_id = (select auth.uid()));
create policy channel_connections_owner_read on public.channel_connections for select to authenticated using (owner_id = (select auth.uid()));
create policy generation_spend_owner_read on public.generation_spend for select to authenticated using (owner_id = (select auth.uid()));
create policy publication_jobs_owner_read on public.publication_jobs for select to authenticated using (owner_id = (select auth.uid()));
create policy publication_jobs_owner_insert on public.publication_jobs for insert to authenticated with check (owner_id = (select auth.uid()) and status = any (array['draft'::text, 'awaiting_approval'::text]));
create policy publication_jobs_owner_update on public.publication_jobs for update to authenticated using (owner_id = (select auth.uid()) and status = any (array['draft'::text, 'awaiting_approval'::text, 'approved'::text])) with check (owner_id = (select auth.uid()) and status = any (array['draft'::text, 'awaiting_approval'::text, 'cancelled'::text]));
create policy publication_jobs_owner_delete on public.publication_jobs for delete to authenticated using (owner_id = (select auth.uid()) and status = any (array['draft'::text, 'awaiting_approval'::text, 'cancelled'::text]));
create policy campaigns_owner_all on public.campaigns for all to authenticated using (owner_id = (select auth.uid()))
  with check (owner_id = (select auth.uid()) and (project_id is null or exists (select 1 from public.projects p where p.id = campaigns.project_id and p.owner_id = (select auth.uid()))));

-- Storage: private bucket "generated-assets"; each user only touches objects under a folder named with their own uid.
insert into storage.buckets (id, name, public) values ('generated-assets', 'generated-assets', false) on conflict (id) do nothing;
create policy "generated assets select own" on storage.objects for select to authenticated using (bucket_id = 'generated-assets' and (storage.foldername(name))[1] = (auth.uid())::text);
create policy "generated assets insert own" on storage.objects for insert to authenticated with check (bucket_id = 'generated-assets' and (storage.foldername(name))[1] = (auth.uid())::text);
create policy "generated assets update own" on storage.objects for update to authenticated using (bucket_id = 'generated-assets' and (storage.foldername(name))[1] = (auth.uid())::text) with check (bucket_id = 'generated-assets' and (storage.foldername(name))[1] = (auth.uid())::text);
create policy "generated assets delete own" on storage.objects for delete to authenticated using (bucket_id = 'generated-assets' and (storage.foldername(name))[1] = (auth.uid())::text);

-- Table privileges (Production starts from Supabase default grants to anon/authenticated/service_role, then restricts these):
revoke all on public.campaigns, public.channel_connections, public.generation_spend, public.research_cache from anon;
revoke all on public.channel_connections from authenticated;
revoke insert, update, delete, truncate, references, trigger on public.generation_spend from authenticated;


-- ===== pending/20261101120000_job_queue.sql =====
-- Cerebro Studio · Fase 4B · cola de trabajos + presupuestos agregados
-- ESTADO: PENDIENTE DE APROBACION. NO esta en supabase/migrations a proposito:
-- ninguna herramienta de despliegue la aplica. Solo aditiva (tablas/funciones nuevas);
-- no toca ninguna tabla existente. Reversible con 20261101120000_job_queue.rollback.sql.

-- ───────────────────────── job_queue ─────────────────────────
create table if not exists public.job_queue (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null references auth.users(id) on delete cascade,
  project_id uuid references public.projects(id) on delete set null,
  kind text not null check (char_length(kind) between 1 and 64),
  status text not null default 'pending'
    check (status in ('pending','running','awaiting_approval','completed','failed','cancelled')),
  -- Ambito de idempotencia: (propietario, tipo, clave). Misma clave = mismo trabajo.
  idempotency_key text not null check (char_length(idempotency_key) between 8 and 200),
  payload jsonb not null default '{}'::jsonb check (jsonb_typeof(payload) = 'object'),
  payload_hash text not null,                 -- las aprobaciones se sellan contra este hash
  priority int not null default 100 check (priority between 0 and 1000),   -- menor = antes
  available_at timestamptz not null default now(),
  attempts int not null default 0 check (attempts >= 0),
  max_attempts int not null default 3 check (max_attempts between 1 and 10),
  -- Lease: solo el ejecutor con claim_token vigente puede escribir.
  executor_id text,
  claim_token uuid,
  locked_at timestamptz,
  lease_expires_at timestamptz,
  cancel_requested boolean not null default false,
  current_step text,
  steps jsonb not null default '[]'::jsonb check (jsonb_typeof(steps) = 'array'),
  result jsonb,
  error jsonb,                                -- {code, message, httpStatus?, retryable}
  awaiting_reason text,                       -- por que espera a una persona
  -- Presupuesto: estimacion declarada al encolar (por unidad) y modo.
  budget_estimate jsonb not null default '{}'::jsonb check (jsonb_typeof(budget_estimate) = 'object'),
  dry_run boolean not null default true,      -- simulacion por defecto
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  started_at timestamptz,
  finished_at timestamptz,
  constraint job_queue_idem_unique unique (owner_id, kind, idempotency_key),
  constraint job_queue_running_has_lease check (
    status <> 'running' or (executor_id is not null and claim_token is not null and lease_expires_at is not null)
  )
);

create index if not exists job_queue_claim_idx on public.job_queue (priority, available_at)
  where status = 'pending';
create index if not exists job_queue_lease_idx on public.job_queue (lease_expires_at)
  where status = 'running';
create index if not exists job_queue_owner_idx on public.job_queue (owner_id, created_at desc);
create index if not exists job_queue_project_idx on public.job_queue (project_id) where project_id is not null;

-- ───────────────────────── aprobaciones selladas ─────────────────────────
create table if not exists public.job_approvals (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null references auth.users(id) on delete cascade,
  job_id uuid not null references public.job_queue(id) on delete cascade,
  step text not null,
  action text not null check (action in ('spend','render_batch','publish','retry_uncertain')),
  payload_hash text not null,                  -- se invalida si el payload del trabajo cambia
  max_amount jsonb not null default '{}'::jsonb,  -- tope por unidad, p. ej. {"eur":0}
  expires_at timestamptz not null,
  revoked_at timestamptz,
  created_at timestamptz not null default now(),
  constraint job_approvals_unique unique (job_id, step, action)
);
create index if not exists job_approvals_job_idx on public.job_approvals (job_id);

-- ───────────────────────── presupuestos ─────────────────────────
create table if not exists public.budget_limits (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null references auth.users(id) on delete cascade,
  provider text not null check (char_length(provider) between 1 and 64),
  project_id uuid references public.projects(id) on delete cascade,  -- null = todos los proyectos
  unit text not null check (unit in ('eur','usd','credits','quota')),
  daily_limit numeric(14,4) not null default 0 check (daily_limit >= 0),  -- 0 = nada autorizado
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create unique index if not exists budget_limits_scope_idx on public.budget_limits
  (owner_id, provider, coalesce(project_id, '00000000-0000-0000-0000-000000000000'::uuid), unit);

create table if not exists public.budget_entries (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null references auth.users(id) on delete cascade,
  job_id uuid references public.job_queue(id) on delete set null,
  step text,
  provider text not null,
  project_id uuid references public.projects(id) on delete set null,
  unit text not null check (unit in ('eur','usd','credits','quota')),
  day date not null,
  reserved numeric(14,4) not null check (reserved >= 0),
  actual numeric(14,4) check (actual >= 0),
  state text not null default 'reserved' check (state in ('reserved','uncertain','settled','released')),
  idempotency_key text not null,               -- una reserva por (trabajo, paso, unidad)
  created_at timestamptz not null default now(),
  settled_at timestamptz,
  constraint budget_entries_idem unique (owner_id, idempotency_key)
);
create index if not exists budget_entries_day_idx on public.budget_entries (owner_id, provider, unit, day);

-- ───────────────────────── RLS ─────────────────────────
alter table public.job_queue enable row level security;
alter table public.job_approvals enable row level security;
alter table public.budget_limits enable row level security;
alter table public.budget_entries enable row level security;

-- El usuario ve y cancela lo suyo. NO puede marcar completado, cambiar estado, lease ni presupuesto:
-- esas escrituras solo las hace el ejecutor con service_role (que salta RLS).
do $$
begin
  if not exists (select 1 from pg_policies where schemaname='public' and tablename='job_queue' and policyname='job_queue_owner_select') then
    create policy job_queue_owner_select on public.job_queue for select using (owner_id = (select auth.uid()));
  end if;
  if not exists (select 1 from pg_policies where schemaname='public' and tablename='job_approvals' and policyname='job_approvals_owner_select') then
    create policy job_approvals_owner_select on public.job_approvals for select using (owner_id = (select auth.uid()));
  end if;
  if not exists (select 1 from pg_policies where schemaname='public' and tablename='budget_limits' and policyname='budget_limits_owner_select') then
    create policy budget_limits_owner_select on public.budget_limits for select using (owner_id = (select auth.uid()));
  end if;
  if not exists (select 1 from pg_policies where schemaname='public' and tablename='budget_entries' and policyname='budget_entries_owner_select') then
    create policy budget_entries_owner_select on public.budget_entries for select using (owner_id = (select auth.uid()));
  end if;
end $$;
-- Sin politicas de insert/update/delete para usuarios: crear, cancelar y aprobar pasan por
-- rutas de servidor que validan sesion y propiedad y escriben con service_role.

revoke all on public.job_queue, public.job_approvals, public.budget_limits, public.budget_entries from anon, authenticated;
grant select on public.job_queue, public.job_approvals, public.budget_limits, public.budget_entries to authenticated;

-- ───────────────────────── funciones atomicas ─────────────────────────
-- Reclamar: un solo ejecutor gana (FOR UPDATE SKIP LOCKED). Recupera tambien leases caducados.
create or replace function public.claim_next_job(p_executor text, p_lease_seconds int default 60, p_kinds text[] default null)
returns public.job_queue
language plpgsql security definer set search_path = public, pg_temp as $$
declare j public.job_queue;
begin
  select * into j from public.job_queue
   where ((status = 'pending' and available_at <= now())
       or (status = 'running' and lease_expires_at < now()))
     and (p_kinds is null or kind = any(p_kinds))   -- un worker solo reclama tipos que sabe ejecutar
   order by priority, available_at
   for update skip locked
   limit 1;
  if not found then return null; end if;
  update public.job_queue set
      status = 'running', executor_id = p_executor, claim_token = gen_random_uuid(),
      locked_at = now(), lease_expires_at = now() + make_interval(secs => p_lease_seconds),
      attempts = attempts + 1, started_at = coalesce(started_at, now()), updated_at = now()
    where id = j.id
    returning * into j;
  return j;
end $$;

-- Reserva atomica: serializa por (propietario, proveedor, unidad, dia) con advisory lock.
-- Devuelve true solo si cabe en el limite. Sin limite configurado = limite 0.
create or replace function public.reserve_budget(
  p_owner uuid, p_job uuid, p_step text, p_provider text, p_project uuid,
  p_unit text, p_amount numeric, p_key text)
returns boolean
language plpgsql security definer set search_path = public, pg_temp as $$
declare lim numeric; used numeric; today date := (now() at time zone 'utc')::date; k text := p_key || ':' || p_unit;   -- misma convencion que settle/release
begin
  if p_amount is null or p_amount < 0 then return false; end if;   -- precio desconocido = bloqueo
  perform pg_advisory_xact_lock(hashtextextended(p_owner::text || p_provider || p_unit || today::text, 0));
  if exists (select 1 from public.budget_entries where owner_id = p_owner and idempotency_key = k) then
    return true;                                                    -- reintento: no duplica
  end if;
  select coalesce(min(daily_limit), 0) into lim from public.budget_limits
   where owner_id = p_owner and provider = p_provider and unit = p_unit
     and (project_id is null or project_id = p_project);
  select coalesce(sum(case when state = 'settled' then actual when state in ('reserved','uncertain') then reserved else 0 end), 0)
    into used from public.budget_entries
   where owner_id = p_owner and provider = p_provider and unit = p_unit and day = today and state <> 'released';
  if used + p_amount > lim then return false; end if;
  insert into public.budget_entries (owner_id, job_id, step, provider, project_id, unit, day, reserved, idempotency_key)
    values (p_owner, p_job, p_step, p_provider, p_project, p_unit, today, p_amount, k);
  return true;
end $$;


-- Escrituras del ejecutor con fencing: solo el dueno del lease vigente (claim_token) puede escribir.
create or replace function public.heartbeat_job(p_id uuid, p_token uuid, p_lease_seconds int default 60)
returns boolean language plpgsql security definer set search_path = public, pg_temp as $$
begin
  update public.job_queue set lease_expires_at = now() + make_interval(secs => p_lease_seconds), updated_at = now()
   where id = p_id and claim_token = p_token and status = 'running' and lease_expires_at >= now();
  return found;
end $$;

create or replace function public.save_job_steps(p_id uuid, p_token uuid, p_steps jsonb, p_current text)
returns boolean language plpgsql security definer set search_path = public, pg_temp as $$
begin
  update public.job_queue set steps = p_steps, current_step = p_current, updated_at = now()
   where id = p_id and claim_token = p_token and status = 'running' and lease_expires_at >= now();
  return found;
end $$;

-- Termina, espera aprobacion o devuelve a la cola (p_status = 'pending' + p_available_at). Libera el lease.
create or replace function public.finish_job(p_id uuid, p_token uuid, p_status text, p_result jsonb default null,
  p_error jsonb default null, p_awaiting text default null, p_available_at timestamptz default null)
returns boolean language plpgsql security definer set search_path = public, pg_temp as $$
begin
  if p_status not in ('pending','awaiting_approval','completed','failed','cancelled') then return false; end if;
  update public.job_queue set status = p_status, result = coalesce(p_result, result), error = p_error,
      awaiting_reason = p_awaiting, available_at = coalesce(p_available_at, available_at),
      executor_id = null, claim_token = null, lease_expires_at = null, locked_at = null,
      finished_at = case when p_status in ('completed','failed','cancelled') then now() else finished_at end,
      updated_at = now()
   where id = p_id and claim_token = p_token and status = 'running' and lease_expires_at >= now();
  return found;
end $$;

-- Los estados terminales son inmutables: nada puede «resucitar» un trabajo completado, fallido o cancelado.
create or replace function public.job_queue_terminal_guard() returns trigger language plpgsql as $$
begin
  if old.status in ('completed','failed','cancelled') and new.status is distinct from old.status then
    raise exception 'job % ya esta en estado terminal %', old.id, old.status using errcode = 'check_violation';
  end if;
  return new;
end $$;
drop trigger if exists job_queue_terminal_guard on public.job_queue;
create trigger job_queue_terminal_guard before update on public.job_queue for each row execute function public.job_queue_terminal_guard();

-- Fuente unica de verdad de las aprobaciones: devuelve el problema (o null si es valida).
create or replace function public.check_approval(p_job uuid, p_step text, p_action text)
returns text language plpgsql stable security definer set search_path = public, pg_temp as $$
declare a public.job_approvals; j public.job_queue;
begin
  select * into j from public.job_queue where id = p_job;
  if not found then return 'job_not_found'; end if;
  select * into a from public.job_approvals where job_id = p_job and step = p_step and action = p_action;
  if not found then return 'approval_missing'; end if;
  if a.owner_id <> j.owner_id then return 'approval_invalidated'; end if;
  if a.revoked_at is not null then return 'approval_revoked'; end if;
  if a.expires_at <= now() then return 'approval_expired'; end if;
  if a.payload_hash <> j.payload_hash then return 'approval_invalidated'; end if;
  return null;
end $$;

-- Presupuesto: conciliar, liberar (solo lo NO incierto) y resolver lo incierto a mano.
-- Las claves de reserva son «<base>:<unidad>»; starts_with evita comodines LIKE.
create or replace function public.settle_budget(p_owner uuid, p_keybase text, p_unit text, p_actual numeric)
returns boolean language plpgsql security definer set search_path = public, pg_temp as $$
begin
  update public.budget_entries set state = 'settled', actual = coalesce(p_actual, reserved), settled_at = now()
   where owner_id = p_owner and idempotency_key = p_keybase || ':' || p_unit and state in ('reserved','uncertain');
  return found;
end $$;

create or replace function public.release_budget(p_owner uuid, p_keybase text)
returns int language plpgsql security definer set search_path = public, pg_temp as $$
declare n int;
begin
  update public.budget_entries set state = 'released', settled_at = now()
   where owner_id = p_owner and starts_with(idempotency_key, p_keybase || ':') and state = 'reserved';   -- 'uncertain' NO se libera
  get diagnostics n = row_count;
  return n;
end $$;

create or replace function public.mark_budget_uncertain(p_owner uuid, p_keybase text)
returns int language plpgsql security definer set search_path = public, pg_temp as $$
declare n int;
begin
  update public.budget_entries set state = 'uncertain'
   where owner_id = p_owner and starts_with(idempotency_key, p_keybase || ':') and state = 'reserved';
  get diagnostics n = row_count;
  return n;
end $$;

-- Solo una persona (via ruta de servidor) decide el destino de lo incierto: cobrado (actual) o no cobrado.
create or replace function public.resolve_uncertain_budget(p_owner uuid, p_keybase text, p_charged boolean, p_actual numeric default null)
returns int language plpgsql security definer set search_path = public, pg_temp as $$
declare n int;
begin
  update public.budget_entries set
      state = case when p_charged then 'settled' else 'released' end,
      actual = case when p_charged then coalesce(p_actual, reserved) else actual end, settled_at = now()
   where owner_id = p_owner and starts_with(idempotency_key, p_keybase || ':') and state = 'uncertain';
  get diagnostics n = row_count;
  return n;
end $$;

-- ───────────────────────── API para el adaptador (todo via RPC; nada de SQL suelto desde la app) ─────────────────────────
-- Encolar: idempotente por (owner, kind, clave). Misma clave con OTRO payload no crea nada y avisa (payload_mismatch).
create or replace function public.enqueue_job(p_owner uuid, p_project uuid, p_kind text, p_key text, p_payload jsonb,
  p_payload_hash text, p_priority int default 100, p_max_attempts int default 3, p_dry_run boolean default true)
returns jsonb language plpgsql security definer set search_path = public, pg_temp as $$
declare j public.job_queue; made boolean := true;
begin
  if p_project is not null and not exists (select 1 from public.projects where id = p_project and owner_id = p_owner) then
    raise exception 'el proyecto % no pertenece al propietario', p_project using errcode = 'insufficient_privilege';
  end if;
  insert into public.job_queue (owner_id, project_id, kind, idempotency_key, payload, payload_hash, priority, max_attempts, dry_run)
    values (p_owner, p_project, p_kind, p_key, coalesce(p_payload, '{}'::jsonb), p_payload_hash, p_priority, p_max_attempts, p_dry_run)
    on conflict (owner_id, kind, idempotency_key) do nothing
    returning * into j;
  if not found then
    made := false;
    select * into j from public.job_queue where owner_id = p_owner and kind = p_kind and idempotency_key = p_key;
  end if;
  return jsonb_build_object('job', to_jsonb(j), 'created', made, 'payload_mismatch', (not made) and j.payload_hash <> p_payload_hash);
end $$;

create or replace function public.get_job(p_id uuid) returns jsonb
language sql stable security definer set search_path = public, pg_temp as $$ select to_jsonb(j) from public.job_queue j where j.id = p_id $$;

create or replace function public.request_cancel_job(p_owner uuid, p_id uuid) returns boolean
language plpgsql security definer set search_path = public, pg_temp as $$
begin
  update public.job_queue set
      status = case when status = 'running' then status else 'cancelled' end,
      cancel_requested = true, updated_at = now(),
      finished_at = case when status = 'running' then finished_at else now() end
   where id = p_id and owner_id = p_owner and status in ('pending','running','awaiting_approval');
  return found;
end $$;

create or replace function public.resume_job(p_owner uuid, p_id uuid) returns boolean
language plpgsql security definer set search_path = public, pg_temp as $$
begin
  update public.job_queue set status = 'pending', awaiting_reason = null, available_at = now(), updated_at = now()
   where id = p_id and owner_id = p_owner and status = 'awaiting_approval';
  return found;
end $$;

create or replace function public.grant_approval(p_owner uuid, p_job uuid, p_step text, p_action text, p_payload_hash text,
  p_max_amount jsonb, p_expires timestamptz) returns boolean
language plpgsql security definer set search_path = public, pg_temp as $$
begin
  if not exists (select 1 from public.job_queue where id = p_job and owner_id = p_owner) then return false; end if;
  insert into public.job_approvals (owner_id, job_id, step, action, payload_hash, max_amount, expires_at)
    values (p_owner, p_job, p_step, p_action, p_payload_hash, coalesce(p_max_amount, '{}'::jsonb), p_expires)
    on conflict (job_id, step, action) do update set payload_hash = excluded.payload_hash, max_amount = excluded.max_amount,
      expires_at = excluded.expires_at, revoked_at = null;
  return true;
end $$;

create or replace function public.revoke_approval(p_owner uuid, p_job uuid, p_step text, p_action text) returns boolean
language plpgsql security definer set search_path = public, pg_temp as $$
begin
  update public.job_approvals set revoked_at = now()
   where owner_id = p_owner and job_id = p_job and step = p_step and action = p_action and revoked_at is null;
  return found;
end $$;

create or replace function public.get_approval(p_job uuid, p_step text, p_action text) returns jsonb
language sql stable security definer set search_path = public, pg_temp as $$
  select to_jsonb(a) from public.job_approvals a where a.job_id = p_job and a.step = p_step and a.action = p_action $$;

create or replace function public.set_budget_limit(p_owner uuid, p_provider text, p_project uuid, p_unit text, p_limit numeric) returns boolean
language plpgsql security definer set search_path = public, pg_temp as $$
begin
  update public.budget_limits set daily_limit = greatest(0, p_limit), updated_at = now()
   where owner_id = p_owner and provider = p_provider and unit = p_unit and project_id is not distinct from p_project;
  if not found then
    insert into public.budget_limits (owner_id, provider, project_id, unit, daily_limit) values (p_owner, p_provider, p_project, p_unit, greatest(0, p_limit));
  end if;
  return true;
end $$;

create or replace function public.budget_used(p_owner uuid, p_provider text, p_unit text) returns numeric
language sql stable security definer set search_path = public, pg_temp as $$
  select coalesce(sum(case when state = 'settled' then actual else reserved end), 0) from public.budget_entries
   where owner_id = p_owner and provider = p_provider and unit = p_unit and day = (now() at time zone 'utc')::date and state <> 'released' $$;

-- Reserva multi-unidad TODO O NADA en una sola transaccion. p_costs = {"eur": 0.5, "quota": 100}; un null = precio desconocido.
create or replace function public.reserve_budget_multi(p_owner uuid, p_job uuid, p_step text, p_provider text, p_project uuid,
  p_costs jsonb, p_key text) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare u text; v jsonb; amt numeric; lim numeric; used numeric; today date := (now() at time zone 'utc')::date;
begin
  if jsonb_typeof(p_costs) <> 'object' then return jsonb_build_object('ok', false, 'code', 'invalid_amount', 'unit', null); end if;
  for u in select k from jsonb_object_keys(p_costs) k order by k loop                     -- orden fijo: sin interbloqueos
    if u not in ('eur','usd','credits','quota') then return jsonb_build_object('ok', false, 'code', 'invalid_amount', 'unit', u); end if;
    v := p_costs -> u;
    if jsonb_typeof(v) = 'null' then return jsonb_build_object('ok', false, 'code', 'unknown_price', 'unit', u); end if;
    if jsonb_typeof(v) <> 'number' or (v #>> '{}')::numeric < 0 then return jsonb_build_object('ok', false, 'code', 'invalid_amount', 'unit', u); end if;
    perform pg_advisory_xact_lock(hashtextextended(p_owner::text || p_provider || u || today::text, 0));
  end loop;
  if (select count(*) from jsonb_object_keys(p_costs)) > 0 and not exists (
       select 1 from jsonb_object_keys(p_costs) k where not exists
         (select 1 from public.budget_entries where owner_id = p_owner and idempotency_key = p_key || ':' || k)) then
    return jsonb_build_object('ok', true, 'reused', true);                                  -- reintento: no duplica
  end if;
  for u in select k from jsonb_object_keys(p_costs) k order by k loop
    amt := (p_costs ->> u)::numeric;
    select coalesce(min(daily_limit), 0) into lim from public.budget_limits
     where owner_id = p_owner and provider = p_provider and unit = u and (project_id is null or project_id = p_project);
    select coalesce(sum(case when state = 'settled' then actual else reserved end), 0) into used from public.budget_entries
     where owner_id = p_owner and provider = p_provider and unit = u and day = today and state <> 'released';
    if used + amt > lim then return jsonb_build_object('ok', false, 'code', 'budget_exhausted', 'unit', u); end if;
  end loop;
  for u in select k from jsonb_object_keys(p_costs) k order by k loop
    insert into public.budget_entries (owner_id, job_id, step, provider, project_id, unit, day, reserved, idempotency_key)
      values (p_owner, p_job, p_step, p_provider, p_project, u, today, (p_costs ->> u)::numeric, p_key || ':' || u)
      on conflict (owner_id, idempotency_key) do nothing;
  end loop;
  return jsonb_build_object('ok', true, 'reused', false);
end $$;

-- Solo service_role ejecuta las funciones privilegiadas. Ningun otro rol (ni public) puede.
do $$
declare f record;
begin
  for f in select p.oid::regprocedure as sig from pg_proc p join pg_namespace n on n.oid = p.pronamespace
            where n.nspname = 'public' and p.proname in ('claim_next_job','reserve_budget','heartbeat_job','save_job_steps','finish_job',
              'check_approval','settle_budget','release_budget','mark_budget_uncertain','resolve_uncertain_budget',
              'enqueue_job','get_job','request_cancel_job','resume_job','grant_approval','revoke_approval','get_approval','set_budget_limit','budget_used','reserve_budget_multi') loop
    execute format('revoke all on function %s from public, anon, authenticated', f.sig);
    execute format('grant execute on function %s to service_role', f.sig);
  end loop;
end $$;

-- ===== pending/20261102120000_storyboard_from_script_rpc.sql =====
-- PROPUESTA PARA REVISION. NO aplicada en ningun Supabase. SIN PROBAR contra una base real (solo revisada).
-- Objetivo: crear/reanudar el storyboard de un guion de forma ATOMICA e idempotente (hoy la pantalla lo hace en dos pasos).
-- SECURITY INVOKER: se ejecuta con los permisos y la RLS del usuario que llama; no eleva privilegios.
create or replace function public.create_storyboard_from_script(p_script_id uuid, p_scenes jsonb)
returns uuid
language plpgsql
security invoker
set search_path = public, pg_temp
as $$
declare
  v_script public.scripts%rowtype;
  v_board uuid;
begin
  if auth.uid() is null then raise exception 'not_authenticated' using errcode = '28000'; end if;
  -- Serializa llamadas concurrentes sobre el MISMO guion (la prueba con 10 sesiones paralelas creó 2 storyboards sin este bloqueo).
  perform pg_advisory_xact_lock(hashtextextended('storyboard_from_script:' || p_script_id::text, 0));
  select * into v_script from public.scripts where id = p_script_id and owner_id = auth.uid();
  if not found then raise exception 'script_not_found' using errcode = 'P0002'; end if;

  select id into v_board from public.storyboards where script_id = p_script_id and owner_id = auth.uid() order by created_at desc limit 1;
  if v_board is null then
    insert into public.storyboards (owner_id, project_id, script_id, title, aspect_ratio)
    values (auth.uid(), v_script.project_id, p_script_id, v_script.title || ' · guion v' || v_script.version, '16:9')
    returning id into v_board;
  end if;

  -- Solo inserta las escenas cuya clave (id de seccion o hook/CTA) aún no existe; posiciones libres; no toca las existentes.
  insert into public.scenes (owner_id, storyboard_id, position, duration_ms, narration, metadata)
  select auth.uid(), v_board,
         coalesce((select max(position) from public.scenes where storyboard_id = v_board), 0) + row_number() over (order by (e->>'position')::int),
         (e->>'duration_ms')::int, e->>'narration', coalesce(e->'metadata', '{}'::jsonb)
  from jsonb_array_elements(p_scenes) as e
  where not exists (
    select 1 from public.scenes s
    where s.storyboard_id = v_board
      and coalesce(s.metadata->>'script_section_id', 'h:' || (s.metadata->>'heading')) = coalesce(e->'metadata'->>'script_section_id', 'h:' || (e->'metadata'->>'heading'))
  );
  return v_board;
end;
$$;
revoke all on function public.create_storyboard_from_script(uuid, jsonb) from public, anon;
grant execute on function public.create_storyboard_from_script(uuid, jsonb) to authenticated;

-- ===== pending/20261102130000_scenes_concurrency_and_reorder.sql =====
-- PROPUESTA PARA REVISION. NO aplicada en ningun Supabase. SIN PROBAR contra una base real.
-- 1) Control de concurrencia para escenas (hoy `scenes` no tiene updated_at).
alter table public.scenes add column if not exists updated_at timestamptz not null default now();
create or replace function public.touch_scene_updated_at() returns trigger language plpgsql set search_path = public, pg_temp as $$
begin new.updated_at := now(); return new; end $$;
drop trigger if exists scenes_touch_updated_at on public.scenes;
create trigger scenes_touch_updated_at before update on public.scenes for each row execute function public.touch_scene_updated_at();

-- 2) Reordenar de forma ATOMICA: p_ids en el orden final deseado (debe ser exactamente el conjunto de escenas del storyboard).
-- SECURITY INVOKER: respeta la RLS del usuario.
create or replace function public.reorder_scenes(p_storyboard uuid, p_ids uuid[])
returns void language plpgsql security invoker set search_path = public, pg_temp as $$
declare v_count int;
begin
  if auth.uid() is null then raise exception 'not_authenticated' using errcode = '28000'; end if;
  select count(*) into v_count from public.scenes where storyboard_id = p_storyboard and owner_id = auth.uid();
  if v_count <> coalesce(array_length(p_ids, 1), 0) or exists (
    select 1 from unnest(p_ids) as i(id) where not exists (select 1 from public.scenes s where s.id = i.id and s.storyboard_id = p_storyboard and s.owner_id = auth.uid())
  ) then raise exception 'scene_set_mismatch' using errcode = '22023'; end if;
  update public.scenes set position = position + 1000000 where storyboard_id = p_storyboard and owner_id = auth.uid();
  update public.scenes s set position = o.ord from unnest(p_ids) with ordinality as o(id, ord) where s.id = o.id;
end $$;
revoke all on function public.reorder_scenes(uuid, uuid[]) from public, anon;
grant execute on function public.reorder_scenes(uuid, uuid[]) to authenticated;

